@observe(name="memory_storage", as_type="trace") async def store_conversation_memory( self, user_id: str, conversation_id: str, conversation_history: List[Dict[str, str]], platform: str = "telegram" ) -> bool: """Store conversation turn in agentic-memories service.""" start_time = time.time()
# ... circuit breaker check ...
try: # Build metadata metadata = { "platform": platform, "conversation_id": conversation_id }
# Attempt to store in agentic-memories async with MemoryClient() as memory_client: result = await memory_client.store_memory(user_id, conversation_history, metadata)
# ... success handling ... return True
except (MemoryNetworkError, MemoryAPIError) as e: # ... error handling ... return False

@observe(name="profile_cache_load", as_type="span") async def load_profile_from_cache(self, user_id: str) -> Dict[str, Any]: """Load user profile from Redis cache (non-blocking, <10ms).""" start_time = time.time()
try: cache_key = f"profile:{user_id}" cached_data = await self.redis_client.get(cache_key)
if cached_data: # Cache hit - SILENT (too fast to show) profile = json.loads(cached_data) profile["cached"] = True return profile else: # Cache miss - return empty profile # Background refresh will populate it empty_profile = { "user_id": user_id, "completeness": 0, "cached": False, ... } return empty_profile

if not tool_calls:
    # No tool calls - LLM returned final content
    # Now stream the final response
    logger.info(
        "No tool calls, streaming final response",
        extra={
            "conversation_id": conversation_id,
            "tool_calls_made": tool_call_count
        }
    )

    # Stream tokens from LLM
    async for event in llm_client.stream_chat_completion(
        conversation_messages,
        tools=tools,
        mcp_client=mcp_client
    ):
